 private void apply(boolean restore){if(busy)return;SettingsStyle s=draft;setBusy(true);status.setText("Saving…");worker.execute(()->{boolean ok;if(restore)ok=SettingsPreferences.stop(this);else{String id=GuardReader.inspectEnabled();ok=SettingsCompatibility.supported(this)&&(RecoveryStore.enabledAllowed(this,id)||(RootGuardCommand.enableClock(SystemClock.elapsedRealtime()+8000)&&RecoveryStore.allowEnabled(this)))&&SettingsPreferences.activate(this,s);}runOnUiThread(()->{if(closed)return;if(!ok){setBusy(false);status.setText("Could not apply. Check recovery and the supported Settings APK.");return;}refresh(restore);});});}
